insert into public.questions
(book,book_name,chapter,question,difficulty,option_a,option_b,option_c,option_d,correct_answer,explanation,hint,source_type,order_index) values
('oseias','Oséias',1,'Qual é o nome do profeta que recebeu de Deus a ordem de se casar com uma mulher de prostituição?','facil','Miquéias','Amós','Oséias','Joel','C','Oséias 1:2 identifica o próprio profeta como aquele que recebeu essa ordem.','O nome do livro é também o nome do profeta.','texto_biblico',1),
('oseias','Oséias',11,'Em Oséias 11, como Deus descreve seu relacionamento com Israel?','facil','Como um rei estrangeiro','Como um guerreiro derrotado','Como um comerciante','Como um pai que ensinou seu filho a andar','D','Oséias 11:1-3 usa a imagem de Deus ensinando Efraim a andar e tomando-o nos braços.','A imagem é de cuidado paternal.','texto_biblico',2),
('oseias','Oséias',6,'O que Oséias 6:6 diz que Deus deseja mais do que sacrifícios?','medio','Construções','Conhecimento de Deus','Vitórias militares','Riquezas','B','Oséias 6:6 afirma que Deus deseja misericórdia e conhecimento de Deus mais do que holocaustos e sacrifícios.','A resposta envolve conhecer a Deus.','texto_biblico',3),
('oseias','Oséias',14,'Qual é o convite final do livro de Oséias?','medio','Escolher um novo rei','Construir um novo templo','Voltar ao Senhor','Fugir para o Egito','C','Oséias 14:1 chama Israel a voltar ao Senhor, pois tropeçou em sua iniquidade.','O capítulo final começa com um chamado de retorno.','texto_biblico',4),
('oseias','Oséias',2,'No simbolismo de Oséias 2, o que representa a infidelidade de Israel?','dificil','A construção do templo','A idolatria e a ruptura da aliança com Deus','A invasão da Assíria apenas','A divisão das tribos no deserto','B','Oséias usa a imagem conjugal para denunciar a infidelidade espiritual de Israel, associada à idolatria.','A metáfora central é a de um casamento rompido.','texto_biblico',5),
('oseias','Oséias',3,'O que Oséias fez para readquirir sua esposa, ilustrando o amor redentor de Deus?','facil','Pagou com prata e cevada','Foi a um tribunal romano','Pediu ajuda ao rei da Assíria','Construiu um novo templo','A','Oséias 3:2 relata que o profeta comprou sua esposa por quinze moedas de prata e certa quantidade de cevada, simbolizando a redenção de Israel.','O preço envolve dinheiro e um grão.','texto_biblico',6),
('oseias','Oséias',4,'Qual acusação abre a controvérsia de Deus com Israel em Oséias 4?','facil','Não há conhecimento de Deus na terra','O rei foi deposto','O templo foi destruído','O povo é rico demais','A','Oséias 4:1 acusa a terra de faltar verdade, misericórdia e conhecimento de Deus.','É uma falta de relacionamento com Deus.','texto_biblico',7),
('oseias','Oséias',13,'Qual pergunta desafiadora sobre a morte aparece em Oséias 13:14?','medio','Quem construirá o templo?','Quando virá o novo rei?','Onde está a arca da aliança?','Onde está, ó morte, o teu aguilhão?','D','Oséias 13:14 desafia a morte e o Seol, texto depois citado em 1 Coríntios 15.','É citado no Novo Testamento sobre a ressurreição.','texto_biblico',8),
('oseias','Oséias',10,'O que Oséias 10:12 convida o povo a semear?','medio','Medo','Discórdia','Ouro','Justiça','D','Oséias 10:12 exorta: semeai para vós a justiça e colhei segundo a bondade.','É um chamado agrícola com sentido moral.','texto_biblico',9),
('oseias','Oséias',5,'Em Oséias 5:15, o que Deus diz que fará até que o povo reconheça sua culpa?','dificil','Voltará ao seu lugar','Abandonará os profetas','Enviará outro dilúvio','Destruirá o mundo','A','Oséias 5:15 apresenta Deus retirando-se até que o povo, em angústia, busque a sua face.','Deus se retira temporariamente.','texto_biblico',10),
('joel','Joel',1,'Qual desastre ocupa grande parte do capítulo 1 de Joel?','facil','Um terremoto','Uma invasão de gafanhotos','Uma enchente','Uma seca no Egito','B','Joel 1 descreve uma devastação causada por gafanhotos e convoca o povo ao lamento e ao jejum.','O desastre é descrito como uma praga de insetos.','texto_biblico',11),
('joel','Joel',2,'O que Deus promete derramar sobre toda carne em Joel 2?','facil','O seu ouro','O seu templo','A sua espada','O seu Espírito','D','Joel 2:28 anuncia: Deus derramará o seu Espírito sobre toda carne.','É a promessa associada a filhos e filhas profetizando.','texto_biblico',12),
('joel','Joel',2,'Qual atitude Joel 2:12-13 pede ao povo?','medio','Construir uma fortaleza','Migrar para outra terra','Parar de orar','Voltar ao Senhor de todo o coração','D','Joel chama o povo a voltar ao Senhor com jejum, choro e pranto, rasgando o coração.','O chamado é interior, não apenas externo.','texto_biblico',13),
('joel','Joel',3,'Segundo Joel 3, onde as nações são reunidas para julgamento?','medio','Monte Carmelo','Vale de Elá','Vale de Josafá','Deserto do Sinai','C','Joel 3:2 e 12 menciona o vale de Josafá como lugar do julgamento das nações.','O nome significa associado ao julgamento do Senhor.','texto_biblico',14),
('joel','Joel',2,'Qual fenômeno é citado junto à promessa do Espírito e aos sinais no céu?','dificil','A chuva cessará por quarenta anos','As montanhas desaparecerão','O mar se tornará doce','O sol se converterá em trevas e a lua em sangue','D','Joel 2:30-31 menciona sinais no céu, incluindo sol em trevas e lua em sangue antes do grande e terrível dia do Senhor.','São sinais celestes.','texto_biblico',15),
('joel','Joel',1,'Quem Joel convoca a despertar e chorar por causa da devastação em Joel 1:5?','facil','Os exércitos vizinhos','Os sacerdotes apenas','Os bêbados','Os reis estrangeiros','C','Joel 1:5 chama os bêbados a despertarem e chorarem pela perda do vinho novo.','Estão associados à bebida.','texto_biblico',16),
('joel','Joel',2,'O que o povo deve tocar em Sião para anunciar o perigo em Joel 2:1?','facil','A trombeta','Os címbalos','O tambor','A harpa','A','Joel 2:1 ordena tocar a trombeta em Sião para soar o alarme.','É um instrumento de alerta.','texto_biblico',17),
('joel','Joel',2,'O que Deus promete restituir em Joel 2:25?','medio','Os anos que o gafanhoto comeu','Os tronos derrubados','As tribos perdidas','As muralhas da cidade','A','Joel 2:25 promete restituir os anos devorados pelo gafanhoto, símbolo de restauração após o juízo.','É uma promessa de compensação pelo tempo perdido.','texto_biblico',18),
('joel','Joel',3,'Em Joel 3:10, o que as nações são chamadas a transformar em espadas?','medio','Suas tendas','As relhas dos seus arados','Seus rebanhos','Seus templos','B','Joel 3:10 inverte a imagem de paz (vista em Miquéias e Isaías), convocando as nações à guerra: batei as relhas em espadas.','É o oposto da imagem de paz de Miquéias 4:3.','texto_biblico',19),
('joel','Joel',2,'Segundo Joel 2:32, o que acontecerá a todo aquele que invocar o nome do Senhor?','dificil','Será salvo','Perderá seus bens','Será exilado','Será esquecido','A','Joel 2:32 promete que todo aquele que invocar o nome do Senhor será salvo, texto citado em Atos 2 e Romanos 10.','É citado por Pedro no dia de Pentecostes.','texto_biblico',20),
('amos','Amós',1,'Qual era a profissão de Amós antes de exercer seu ministério profético?','facil','Rei','Pastor de ovelhas e cultivador de sicômoros','Pescador','Sacerdote','B','Amós 1:1 e 7:14 apresentam Amós como pastor e cultivador de sicômoros.','Ele não se apresenta como membro de uma escola profética.','texto_biblico',21),
('amos','Amós',5,'O que Amós 5:24 diz que deve correr como um rio?','facil','O ouro','O vinho','A guerra','A justiça','D','Amós 5:24 compara a justiça a águas e o juízo à correnteza de um ribeiro perene.','É uma das imagens mais conhecidas do livro.','texto_biblico',22),
('amos','Amós',3,'Qual princípio Amós 3:3 apresenta?','medio','Dois andarão juntos se não houver acordo entre eles','Todo rei é justo','Israel nunca será julgado','Profetas não precisam ouvir Deus','A','Amós 3:3 pergunta se duas pessoas podem andar juntas sem estarem de acordo.','É uma pergunta sobre concordância e caminhada conjunta.','texto_biblico',23),
('amos','Amós',7,'O que Amós vê em uma das primeiras visões do capítulo 7?','medio','Uma escada','Uma arca','Um cesto de frutas de verão','Um carro de fogo','C','Amós 8:1-2 registra a visão de um cesto de frutas de verão, símbolo da proximidade do fim de Israel.','A visão está no capítulo 8.','texto_biblico',24),
('amos','Amós',8,'Na visão do cesto de frutas de verão, qual jogo de palavras aparece?','dificil','Chuva e bênção','Fruta de verão e fim chegou','Templo e altar','Rei e sacerdote','B','Amós 8:2 usa um jogo de palavras em hebraico entre fruta de verão e fim, indicando o fim de Israel.','A visão anuncia que o fim chegou.','texto_biblico',25),
('amos','Amós',4,'Como Amós 4:1 chama as mulheres opressoras de Samaria?','facil','Leoas do deserto','Vacas de Basã','Pombas do vale','Águias da montanha','B','Amós 4:1 usa a expressão vacas de Basã para denunciar mulheres que oprimiam os pobres.','É uma comparação com um animal de pastagem rica.','texto_biblico',26),
('amos','Amós',9,'O que Deus promete restaurar em Amós 9:11?','facil','O tabernáculo caído de Davi','O templo de Baal','O palácio do Egito','A muralha de Nínive','A','Amós 9:11 promete levantar o tabernáculo caído de Davi, texto citado em Atos 15.','É uma promessa messiânica ligada à linhagem de Davi.','texto_biblico',27),
('amos','Amós',2,'Do que Israel é acusado em Amós 2:6, ao vender pessoas?','medio','Vender terras para o Egito','Vender animais sagrados','Vender o justo por prata e o pobre por um par de sandálias','Vender armas para a Assíria','C','Amós 2:6 denuncia a venda do justo por dinheiro e do pobre por um simples par de sandálias.','É uma denúncia de injustiça social extrema.','texto_biblico',28),
('amos','Amós',6,'Contra quem é o "ai" pronunciado em Amós 6:1?','medio','Os estrangeiros pobres','Os pastores humildes','Os que vivem sossegados em Sião','Os sacerdotes fiéis','C','Amós 6:1 pronuncia ai sobre os que vivem despreocupados e confiantes em Sião e em Samaria.','É uma crítica à complacência dos líderes.','texto_biblico',29),
('amos','Amós',7,'Quem ordenou que Amós fugisse para Judá e parasse de profetizar em Betel?','dificil','O rei da Assíria','Um profeta rival','Jeroboão pessoalmente','Amazias, sacerdote de Betel','D','Amós 7:10-13 narra o confronto com Amazias, sacerdote de Betel, que expulsou Amós, ao que o profeta respondeu que não era profeta profissional, mas pastor chamado por Deus.','É o sacerdote do santuário real de Betel.','texto_biblico',30),
('obadias','Obadias',1,'Qual nação é o principal alvo da profecia de Obadias?','facil','Egito','Moabe','Assíria','Edom','D','Obadias é uma profecia contra Edom.','Edom é o povo descendente de Esaú.','texto_biblico',31),
('obadias','Obadias',1,'Edom é associado a qual ancestral?','facil','Isaque','Esaú','Jacó','José','B','Edom está ligado a Esaú, irmão de Jacó, conforme Gênesis.','Esaú recebeu o nome Edom.','texto_biblico',32),
('obadias','Obadias',1,'Por que Edom é condenado em Obadias?','medio','Por cultivar oliveiras','Por construir o templo','Por abandonar o Egito','Por sua violência contra seu irmão Jacó','D','Obadias 10-14 condena a violência e a participação de Edom na desgraça de Judá.','O texto fala de violência contra o irmão.','texto_biblico',33),
('obadias','Obadias',1,'O que Obadias 17 promete que haverá no monte Sião?','medio','Um exército estrangeiro','Uma nova pirâmide','Livramento e santidade','Uma grande frota','C','Obadias 17 afirma que no monte Sião haverá livramento e ele será santo.','É uma promessa para Sião.','texto_biblico',34),
('obadias','Obadias',1,'Qual é a ideia central do final de Obadias sobre o reino?','dificil','O reino será do Senhor','Não haverá restauração','Edom governará para sempre','Babilônia dominará Judá','A','Obadias 21 termina com a declaração de que o reino será do Senhor.','É a frase final do livro.','texto_biblico',35),
('obadias','Obadias',1,'Segundo Obadias 3, o que enganou o coração de Edom?','facil','A fome','A ignorância','A pobreza','A soberba','D','Obadias 3 diz que a soberba do coração de Edom o enganou, confiando em sua posição elevada nas rochas.','É um pecado ligado ao orgulho.','texto_biblico',36),
('obadias','Obadias',1,'Onde Edom habitava, segundo a descrição de Obadias 3?','facil','Nas fendas das rochas, em lugar alto','Em barcos no mar Vermelho','Nas margens do rio Nilo','Em tendas no deserto do Sinai','A','Obadias 3 descreve Edom habitando nas fendas das rochas, confiante em sua altura e segurança.','É uma região montanhosa e fortificada.','texto_biblico',37),
('obadias','Obadias',1,'Qual foi a atitude de Edom quando estrangeiros saquearam Jerusalém, segundo Obadias 11?','medio','Defendeu Jerusalém com seu exército','Ficou de lado e se comportou como um deles','Avisou os profetas com antecedência','Abrigou os refugiados de Judá','B','Obadias 11 acusa Edom de ficar de lado, omisso, comportando-se como um dos invasores.','A culpa envolve omissão e cumplicidade.','texto_biblico',38),
('obadias','Obadias',1,'Qual princípio de reciprocidade aparece em Obadias 15?','medio','Quem semeia pouco colhe muito','Como fizeste, se fará a ti','Não haverá julgamento para nenhuma nação','O rico sempre vencerá','B','Obadias 15 anuncia que o dia do Senhor virá sobre todas as nações e o que Edom fez lhe será retribuído.','É uma lei de causa e efeito no juízo divino.','texto_biblico',39),
('obadias','Obadias',1,'Em Obadias 18, a que a casa de Esaú é comparada diante do fogo de Jacó e José?','dificil','Um rio caudaloso','Ouro puro','Restolho, que será consumido','Uma torre inabalável','C','Obadias 18 descreve a casa de Jacó como fogo e a de Esaú como restolho, que será totalmente consumido.','É um material seco e facilmente inflamável.','texto_biblico',40),
('jonas','Jonas',1,'Para qual cidade Jonas foi enviado para pregar?','facil','Nínive','Babilônia','Jerusalém','Samaria','A','Jonas 1:2 ordena que o profeta vá a Nínive para anunciar sua mensagem.','Era a grande cidade da Assíria.','texto_biblico',41),
('jonas','Jonas',2,'O que engoliu Jonas depois que ele foi lançado ao mar?','facil','Um navio','Um crocodilo','Um grande peixe','Uma baleia mencionada pelo nome','C','Jonas 1:17 diz que o Senhor preparou um grande peixe para engolir Jonas.','O texto chama de grande peixe.','texto_biblico',42),
('jonas','Jonas',3,'Como os ninivitas reagiram à pregação de Jonas?','medio','Prenderam Jonas','Ignoraram a mensagem','Arrependeram-se e proclamaram jejum','Foram para Jerusalém','C','Jonas 3 descreve arrependimento, jejum e clamor a Deus desde o povo até o rei.','O rei também participou do jejum.','texto_biblico',43),
('jonas','Jonas',4,'Por que Jonas ficou descontente depois da misericórdia de Deus para Nínive?','medio','Porque perdeu o barco','Porque não recebeu pagamento','Porque o peixe voltou','Porque Deus não destruiu a cidade','D','Jonas 4:1-2 mostra que Jonas ficou irado porque Deus teve misericórdia e não executou o juízo anunciado.','Jonas já sabia que Deus era misericordioso.','texto_biblico',44),
('jonas','Jonas',4,'Que planta Deus fez crescer para dar sombra a Jonas?','dificil','Uma figueira','Um mamoeiro','Uma videira','Uma planta chamada mamona na tradição portuguesa','D','Jonas 4:6 fala de uma planta que cresceu para fazer sombra; traduções portuguesas variam na identificação, frequentemente usando mamona ou planta de rícino.','O texto enfatiza que Deus preparou a planta e depois a fez secar.','texto_biblico',45),
('jonas','Jonas',1,'Para onde Jonas tentou fugir em vez de ir a Nínive?','facil','Társis','Damasco','Jerusalém','Babilônia','A','Jonas 1:3 relata que o profeta embarcou em um navio rumo a Társis, fugindo da presença do Senhor.','Era uma cidade distante, na direção oposta a Nínive.','texto_biblico',46),
('jonas','Jonas',1,'Como os marinheiros descobriram que Jonas era o responsável pela tempestade?','facil','Lançaram sortes','Consultaram um oráculo egípcio','Jonas confessou espontaneamente logo no início','Um anjo apareceu','A','Jonas 1:7 relata que os marinheiros lançaram sortes, e a sorte caiu sobre Jonas.','É um método antigo de decisão por acaso.','texto_biblico',47),
('jonas','Jonas',2,'O que Jonas declara sobre a salvação em sua oração de dentro do peixe (Jonas 2:9)?','medio','A salvação vem dos sacerdotes','Não há salvação possível','A salvação pertence ao Senhor','A salvação depende dos marinheiros','C','Jonas 2:9 conclui a oração afirmando que a salvação pertence ao Senhor.','É a frase de encerramento da oração no ventre do peixe.','texto_biblico',48),
('jonas','Jonas',3,'Qual foi a mensagem exata que Jonas pregou em Nínive, segundo Jonas 3:4?','medio','Os reis da terra se converterão','Ainda quarenta dias, e Nínive será destruída','Nínive será poupada para sempre','Israel será restaurado em breve','B','Jonas 3:4 registra o anúncio de julgamento em quarenta dias sobre Nínive.','Envolve um prazo específico de dias.','texto_biblico',49),
('jonas','Jonas',4,'No argumento final de Deus a Jonas, quantas pessoas incapazes de discernir a mão direita da esquerda havia em Nínive?','dificil','Um milhão','Mais de cento e vinte mil','Doze mil','Exatamente cem','B','Jonas 4:11 menciona mais de cento e vinte mil pessoas em Nínive, além de muitos animais, como razão da compaixão de Deus.','É um número alto, citado junto com os animais da cidade.','texto_biblico',50),
('miqueias','Miquéias',1,'De onde era Miquéias?','facil','Jericó','Tiro','Moresete','Belém','C','Miquéias 1:1 identifica o profeta como morastita, isto é, de Moresete.','O nome do lugar aparece no início do livro.','texto_biblico',51),
('miqueias','Miquéias',5,'Qual cidade é mencionada como origem do governante prometido?','facil','Nínive','Hebrom','Jerusalém','Belém Efrata','D','Miquéias 5:2 menciona Belém Efrata como pequena entre os clãs de Judá.','É uma cidade pequena de Judá.','texto_biblico',52),
('miqueias','Miquéias',6,'Segundo Miquéias 6:8, o que o Senhor requer do ser humano?','medio','Oferecer milhares de cavalos','Construir grandes palácios','Conquistar outras nações','Praticar a justiça, amar a misericórdia e andar humildemente com Deus','D','Miquéias 6:8 resume o chamado ético em justiça, misericórdia e humildade diante de Deus.','São três verbos/ideias centrais.','texto_biblico',53),
('miqueias','Miquéias',4,'O que Miquéias 4:3 diz que as nações transformarão?','medio','Templos em palácios','Espadas em arados e lanças em foices','Arados em espadas','Rios em estradas','B','Miquéias 4:3 descreve a transformação de armas de guerra em instrumentos agrícolas.','A imagem é de paz e cultivo.','texto_biblico',54),
('miqueias','Miquéias',3,'Qual crítica Miquéias faz aos líderes que deveriam conhecer a justiça?','dificil','Eles reconstruíram Nínive','Eles aborreciam o bem e amavam o mal','Eles abandonaram a agricultura','Eles serviam como sacerdotes fiéis','B','Miquéias 3:1-3 acusa chefes e líderes de odiar o direito e praticar violência contra o povo.','A crítica é dirigida aos líderes de Israel.','texto_biblico',55),
('miqueias','Miquéias',2,'Contra quem é pronunciado o "ai" em Miquéias 2:1?','facil','Os que maquinam a iniquidade em suas camas','As crianças de Judá','Os pastores fiéis','Os estrangeiros pobres','A','Miquéias 2:1 denuncia os que planejam o mal durante a noite e o praticam pela manhã.','O planejamento do mal ocorre à noite.','texto_biblico',56),
('miqueias','Miquéias',7,'O que Miquéias declara em 7:8 mesmo depois de cair?','facil','Fugirei para sempre','Desistirei','Levantar-me-ei','Esconder-me-ei','C','Miquéias 7:8 expressa confiança: ainda que eu caia, levantar-me-ei.','É uma declaração de esperança e confiança.','texto_biblico',57),
('miqueias','Miquéias',7,'Segundo Miquéias 7:19, o que Deus faz com os pecados do seu povo?','medio','Reparte-os entre as nações','Transforma-os em ouro','Lança-os nas profundezas do mar','Guarda-os para sempre','C','Miquéias 7:19 descreve o perdão de Deus como lançar os pecados nas profundezas do mar.','É uma imagem de perdão completo e definitivo.','texto_biblico',58),
('miqueias','Miquéias',3,'Em contraste com falsos profetas, do que Miquéias 3:8 diz estar cheio?','medio','De sabedoria humana apenas','Do poder do Espírito do Senhor','De exércitos','De riquezas materiais','B','Miquéias 3:8 afirma que o profeta está cheio do poder do Espírito do Senhor, de juízo e de força para denunciar o pecado.','É uma afirmação de autoridade profética genuína.','texto_biblico',59),
('miqueias','Miquéias',1,'Durante o reinado de quais reis de Judá Miquéias profetizou, segundo Miquéias 1:1?','dificil','Jotão, Acaz e Ezequias','Herodes e Augusto','Saul, Davi e Salomão','Nabucodonosor e Ciro','A','Miquéias 1:1 situa o ministério do profeta nos dias de Jotão, Acaz e Ezequias, reis de Judá.','São três reis de Judá do período pré-exílico.','texto_biblico',60),
('naum','Naum',1,'Contra qual cidade é dirigida a profecia de Naum?','facil','Damasco','Tiro','Nínive','Jerusalém','C','Naum 1:1 apresenta a sentença contra Nínive.','É a capital assíria.','texto_biblico',61),
('naum','Naum',1,'Como Naum descreve o Senhor em relação à ira?','facil','Fraco e indeciso','Sempre irado sem misericórdia','Tardio em irar-se e grande em poder','Indiferente ao mal','C','Naum 1:3 afirma que o Senhor é tardio em irar-se e grande em poder, sem deixar impune o culpado.','O verso combina paciência e justiça.','texto_biblico',62),
('naum','Naum',2,'Qual imagem aparece na descrição da queda de Nínive?','medio','Carros correndo pelas ruas e portas dos rios abertas','Uma seca no deserto','Um templo sendo reconstruído','Um exército chegando de Jerusalém','A','Naum 2 descreve de forma poética o ataque e a queda de Nínive, incluindo carros e a abertura das portas dos rios.','A cidade está sob ataque.','texto_biblico',63),
('naum','Naum',3,'Por que Nínive é chamada de cidade sanguinária?','medio','Por ser pequena','Por sua violência, mentira e exploração','Por seus muitos jardins','Por sua riqueza agrícola','B','Naum 3:1 acusa Nínive de sangue, mentira, roubo e violência.','A expressão aparece no início do capítulo 3.','texto_biblico',64),
('naum','Naum',3,'Qual é o destino anunciado para Nínive?','dificil','Ser reconstruída como capital de Judá','Ser destruída e não ter cura para sua ferida','Receber um novo templo','Governar o Egito','B','Naum 3:7-19 descreve a queda de Nínive como irreversível diante das nações.','O final do livro não anuncia restauração de Nínive.','texto_biblico',65),
('naum','Naum',1,'Como Naum 1:7 descreve o Senhor para os que confiam nele?','facil','Bom e fortaleza no dia da angústia','Ausente em tempos de crise','Distante e indiferente','Fraco diante dos inimigos','A','Naum 1:7 afirma que o Senhor é bom, fortaleza no dia da angústia, e conhece os que nele confiam.','É um verso de consolo em meio ao anúncio de juízo.','texto_biblico',66),
('naum','Naum',1,'O que Naum 1:15 anuncia que chega sobre os montes?','facil','Uma nuvem de gafanhotos','Um novo exército assírio','Os pés do que anuncia a paz','Uma seca prolongada','C','Naum 1:15 anuncia os pés do mensageiro de boas novas, que proclama a paz após a queda de Nínive.','É uma imagem semelhante à de Isaías 52:7.','texto_biblico',67),
('naum','Naum',3,'A que Nínive é comparada em Naum 3:4 por causa de suas seduções?','medio','Uma noiva fiel','Uma cidade santa','Uma mãe protetora','Uma prostituta encantadora e mestra de feitiços','D','Naum 3:4 acusa Nínive de seduzir nações como uma prostituta encantadora, mestra de feitiçarias.','A acusação envolve sedução e engano.','texto_biblico',68),
('naum','Naum',2,'A que Nínive é comparada em Naum 2:11-12, por causa de sua violência conquistadora?','medio','Um templo sagrado','Um covil de leões','Uma torre pacífica','Um jardim florido','B','Naum 2:11-12 compara Nínive a um covil de leões, cheio de presas, símbolo de sua violência contra outras nações.','É uma comparação com um animal predador feroz.','texto_biblico',69),
('naum','Naum',1,'O que Deus decreta contra a descendência do rei assírio em Naum 1:14?','dificil','Que reconstruiria o templo de Jerusalém','Que se tornaria aliado de Judá','Que seria coroado rei universal','Que seu nome não teria mais descendência','D','Naum 1:14 anuncia que do nome do rei assírio não haveria mais semeadura, e os ídolos de sua casa seriam destruídos.','Envolve o fim da linhagem e dos ídolos do rei.','texto_biblico',70),
('habacuque','Habacuque',1,'O que Habacuque faz principalmente no início do livro?','facil','Interpreta sonhos de Nabucodonosor','Foge para o Egito','Questiona a Deus sobre a violência e a injustiça','Constrói um altar','C','Habacuque começa apresentando perguntas e queixas sobre a violência e a aparente demora da justiça.','O livro tem forma de diálogo entre profeta e Deus.','texto_biblico',71),
('habacuque','Habacuque',2,'Qual frase famosa aparece em Habacuque 2:4?','facil','O Senhor é meu pastor','Tudo é vaidade','O justo viverá pela sua fé','Olho por olho','C','Habacuque 2:4 afirma: o justo viverá pela sua fé/fidelidade, conforme a tradução.','É uma frase central do livro.','texto_biblico',72),
('habacuque','Habacuque',2,'O que Deus manda Habacuque fazer com a visão?','medio','Escrevê-la claramente em tábuas','Entregá-la ao rei do Egito','Apagá-la','Escondê-la','A','Habacuque 2:2 ordena que a visão seja escrita claramente em tábuas para que possa ser lida.','A instrução é escrever a visão.','texto_biblico',73),
('habacuque','Habacuque',3,'Apesar da crise, como termina a oração de Habacuque?','medio','Com silêncio absoluto','Com alegria e confiança em Deus','Com uma coroação','Com uma fuga','B','Habacuque 3:17-19 reconhece a falta de frutos e rebanhos, mas afirma alegria no Senhor e confiança em Deus.','A alegria não depende da prosperidade.','texto_biblico',74),
('habacuque','Habacuque',1,'Qual povo Deus diz que levantará como instrumento de juízo?','dificil','Os filisteus','Os caldeus','Os egípcios','Os edomitas','B','Habacuque 1:6 identifica os caldeus como povo que Deus levantaria para executar juízo.','Caldeus é uma designação associada aos babilônios.','texto_biblico',75),
('habacuque','Habacuque',1,'Como começa o lamento de Habacuque no capítulo 1?','facil','Eis que o rei chegou vitorioso','O templo está reconstruído','Louvado seja o Senhor para sempre','Até quando, Senhor, clamarei e tu não ouvirás?','D','Habacuque 1:2 abre o livro com uma queixa sobre a violência e a aparente demora da resposta de Deus.','É uma pergunta sobre o tempo de espera.','texto_biblico',76),
('habacuque','Habacuque',3,'Com que imagem de força Habacuque 3:19 termina o livro?','facil','Uma frota poderosa','Um exército invencível','Um novo templo de ouro','Pés como os das cervas, andando nas alturas','D','Habacuque 3:19 declara que o Senhor é sua força e faz seus pés como os da cerva, capazes de andar sobre as alturas.','É uma comparação com um animal ágil em terrenos altos.','texto_biblico',77),
('habacuque','Habacuque',2,'O que Habacuque 2:14 promete que encherá a terra?','medio','As águas do dilúvio','O ouro das nações','O conhecimento da glória do Senhor','Os exércitos da Babilônia','C','Habacuque 2:14 promete que a terra se encherá do conhecimento da glória do Senhor, como as águas cobrem o mar.','É uma imagem de plenitude comparada à água do mar.','texto_biblico',78),
('habacuque','Habacuque',2,'Quantos "ais" (pronunciamentos de juízo) Habacuque declara contra o opressor no capítulo 2?','medio','Nenhum','Dez','Dois','Cinco','D','Habacuque 2:6-19 registra cinco declarações de "ai" contra a injustiça e a opressão do conquistador.','É uma série de acusações repetidas com a mesma palavra.','texto_biblico',79),
('habacuque','Habacuque',1,'Na segunda queixa de Habacuque (cap. 1), o que o incomoda sobre o uso dos caldeus por Deus?','dificil','Que Deus use um povo mais ímpio para julgar um povo menos ímpio','Que os caldeus sejam pobres','Que os caldeus adorem o Deus de Israel','Que os caldeus nunca vençam guerras','A','Habacuque 1:12-13 questiona como Deus, de olhos puros, pode usar os caldeus, mais perversos, para punir um povo menos ímpio.','É um questionamento sobre a justiça divina usando um instrumento moralmente pior.','texto_biblico',80),
('sofonias','Sofonias',1,'Quem é identificado como pai de Sofonias?','facil','Amós','Ezequias','Cusi','Hulda','C','Sofonias 1:1 começa com a genealogia e identifica Sofonias como filho de Cusi.','O nome aparece no primeiro versículo.','texto_biblico',81),
('sofonias','Sofonias',1,'Qual expressão marca o anúncio de juízo em Sofonias?','facil','A festa das colheitas','O ano do jubileu','O dia do Senhor','A noite do rei','C','O livro repete a expressão dia do Senhor como momento de juízo.','É o tema temporal mais destacado.','texto_biblico',82),
('sofonias','Sofonias',2,'O que Sofonias 2:3 recomenda buscar?','medio','O Senhor, a justiça e a humildade','Riquezas e poder','A Assíria','Um novo palácio','A','Sofonias 2:3 chama os humildes da terra a buscar o Senhor, a justiça e a humildade.','São três elementos no convite.','texto_biblico',83),
('sofonias','Sofonias',3,'Como termina o livro de Sofonias?','medio','Com a queda de Jerusalém sem esperança','Com uma guerra no Egito','Com promessa de restauração e alegria de Deus sobre seu povo','Com a morte do profeta','C','Sofonias 3:14-20 termina com restauração, reunião dos dispersos e alegria associada à presença de Deus no meio do povo.','O final muda do juízo para a restauração.','texto_biblico',84),
('sofonias','Sofonias',3,'Qual cidade é mencionada entre os alvos de juízo no livro?','dificil','Hebrom','Nínive','Belém','Damasco','B','Sofonias 2:13-15 anuncia juízo contra a Assíria e Nínive, descrita como cidade desolada.','A cidade assíria aparece explicitamente no capítulo 2.','texto_biblico',85),
('sofonias','Sofonias',1,'Qual é a extensão do juízo anunciado logo no início de Sofonias 1:2-3?','facil','Destruição total sobre homens, animais, aves e peixes','Apenas sobre os sacerdotes','Apenas sobre os estrangeiros','Somente sobre a Assíria','A','Sofonias 1:2-3 anuncia uma destruição abrangente sobre toda a face da terra, incluindo homens e animais.','É uma linguagem de juízo cósmico e abrangente.','texto_biblico',86),
('sofonias','Sofonias',3,'O que o Senhor faz por seu povo com alegria, segundo Sofonias 3:17?','facil','Os pune sem misericórdia','Os envia ao exílio','Os abandona no deserto','Canta sobre eles com júbilo','D','Sofonias 3:17 descreve Deus se alegrando e cantando sobre seu povo com júbilo, uma imagem terna do amor divino.','É uma imagem de alegria e canto de Deus.','texto_biblico',87),
('sofonias','Sofonias',1,'Com o que Sofonias 1:12 compara os que estavam acomodados espiritualmente?','medio','Pão fresco','Água corrente e pura','Ouro refinado','Vinho parado sobre as fezes (borra)','D','Sofonias 1:12 fala de buscar com lanternas os que estão acomodados como vinho sobre a borra, indiferentes ao Senhor.','É uma imagem de estagnação e indiferença espiritual.','texto_biblico',88),
('sofonias','Sofonias',2,'Quais grupos de nações são alvo dos oráculos de juízo em Sofonias 2?','medio','Filístia, Moabe, Amom, Cuxe e Assíria','Somente as tribos de Israel','Apenas o Egito','Apenas Roma e Grécia','A','Sofonias 2 traz oráculos de juízo contra Filístia, Moabe, Amom, Cuxe (Etiópia) e a Assíria.','São nações vizinhas de Judá, incluindo a grande potência assíria.','texto_biblico',89),
('sofonias','Sofonias',1,'Segundo a genealogia em Sofonias 1:1, o profeta é apresentado como descendente de qual rei de Judá?','dificil','Davi','Ezequias','Josias, seu contemporâneo','Salomão','B','Sofonias 1:1 traça a genealogia do profeta até Ezequias, sugerindo possível ascendência real.','É um rei reformador anterior a Josias.','texto_biblico',90),
('ageu','Ageu',1,'Qual obra Ageu incentiva o povo a retomar?','facil','O palácio do rei','A reconstrução do templo','A muralha de Jericó','A construção de uma frota','B','Ageu 1:8 chama o povo a subir ao monte, trazer madeira e edificar a casa de Deus.','O templo é chamado de casa do Senhor.','texto_biblico',91),
('ageu','Ageu',1,'Quem governava Judá como governador no contexto de Ageu?','facil','Zorobabel','Saul','Elias','Ezequias','A','Ageu 1:1 identifica Zorobabel, filho de Sealtiel, como governador de Judá.','Ele aparece ao lado de Josué, o sumo sacerdote.','texto_biblico',92),
('ageu','Ageu',1,'Quem era o sumo sacerdote mencionado junto a Zorobabel?','medio','Josué, filho de Jeozadaque','Zadoque','Arão','Eli','A','Ageu 1:1 e outros textos do livro mencionam Josué, filho de Jeozadaque, como sumo sacerdote.','Não é Josué, sucessor de Moisés.','texto_biblico',93),
('ageu','Ageu',2,'O que Deus promete em Ageu 2:9 sobre a glória da casa?','medio','Não haveria templo','A casa seria abandonada','A glória desta última casa seria maior que a da primeira','O templo seria transferido para o Egito','C','Ageu 2:9 promete que a glória desta última casa seria maior que a primeira e anuncia paz.','A comparação é entre a casa anterior e a reconstruída.','texto_biblico',94),
('ageu','Ageu',2,'Qual imagem política aparece em Ageu 2:22?','dificil','A Assíria voltará a governar','Zorobabel será coroado rei de todas as nações','Tronos serão derrubados e reinos serão destruídos','Israel dominará o Egito imediatamente','C','Ageu 2:22 fala em derrubar tronos e destruir forças de reinos, dentro da mensagem escatológica do profeta.','A linguagem é de abalo dos poderes políticos.','texto_biblico',95),
('ageu','Ageu',1,'O que Ageu 1:6 diz sobre o salário de quem trabalhava enquanto negligenciava o templo?','facil','Dobrava a cada semana','Era guardado com segurança','Era posto num saco furado','Vinha do Egito','C','Ageu 1:6 descreve a futilidade econômica do povo, comparando o salário a algo posto num saco furado.','É uma imagem de perda constante e frustração.','texto_biblico',96),
('ageu','Ageu',1,'O que Deus declarou ao povo depois que eles obedeceram e começaram a reconstrução, segundo Ageu 1:13?','facil','Esquecerei o templo','Eu sou convosco','Eu vos abandono','Não voltarei mais','B','Ageu 1:13 registra a palavra de encorajamento do Senhor: Eu sou convosco, diz o Senhor.','É uma promessa de presença divina.','texto_biblico',97),
('ageu','Ageu',2,'O que Ageu 2:7 anuncia que virá depois que Deus abalar céus e terra?','medio','Um novo dilúvio','A queda definitiva de Jerusalém','O fim dos sacrifícios','O Desejado de todas as nações','D','Ageu 2:6-7 anuncia o abalo dos céus e da terra, seguido da vinda do Desejado de todas as nações, enchendo a casa de glória.','É uma expressão messiânica sobre expectativa das nações.','texto_biblico',98),
('ageu','Ageu',1,'Segundo Ageu 1:14, o que o Senhor despertou em Zorobabel, Josué e no povo?','medio','O desejo de fugir para o Egito','O espírito para trabalharem na casa do Senhor','O interesse em construir palácios pessoais','A vontade de abandonar Judá','B','Ageu 1:14 relata que o Senhor despertou o espírito de Zorobabel, Josué e do restante do povo para a obra da reconstrução.','É um despertar coletivo para o trabalho no templo.','texto_biblico',99),
('ageu','Ageu',2,'No versículo final de Ageu (2:23), a que objeto de honra Deus compara Zorobabel?','dificil','Uma espada real','Uma coroa de ouro','Um cetro de ferro','Um anel de selar','D','Ageu 2:23 declara que Deus fará de Zorobabel, seu servo, como um anel de selar, símbolo de honra e escolha divina.','É um objeto usado para autenticar documentos com um selo pessoal.','texto_biblico',100),
('zacarias','Zacarias',1,'Qual era a principal mensagem inicial de Zacarias 1:3?','facil','Fugi para o Egito','Voltai para mim, e eu me voltarei para vós','Escolham outro rei','Não construam o templo','B','Zacarias 1:3 chama o povo a retornar ao Senhor e promete que o Senhor se voltará para eles.','É um chamado ao retorno.','texto_biblico',101),
('zacarias','Zacarias',5,'O que Zacarias vê em uma das visões do capítulo 5?','facil','Um peixe gigante','Uma arca de Noé','Uma coroa de ferro','Um rolo voante','D','Zacarias 5:1 descreve um rolo voante.','É uma visão escrita e voadora.','texto_biblico',102),
('zacarias','Zacarias',4,'Na visão do capítulo 4, o que representa o azeite em relação às duas oliveiras?','medio','A riqueza do rei','A força militar','A água do templo','A provisão do Espírito de Deus','D','Zacarias 4 enfatiza a ação do Espírito: não por força nem por poder, mas pelo Espírito do Senhor.','O verso 6 fornece a chave da visão.','texto_biblico',103),
('zacarias','Zacarias',9,'Qual rei é descrito chegando a Jerusalém montado em um jumento?','medio','O rei da Assíria','Um rei justo e salvador','O faraó do Egito','Nabucodonosor','B','Zacarias 9:9 descreve um rei justo, salvador e humilde, montado em jumento.','A descrição é de um rei humilde.','texto_biblico',104),
('zacarias','Zacarias',12,'Qual expressão aparece em Zacarias 12:10 sobre o futuro arrependimento?','dificil','Jerusalém será abandonada para sempre','Israel será levado ao Egito','Olharão para aquele a quem traspassaram e prantearão','Não haverá arrependimento','C','Zacarias 12:10 descreve derramamento de espírito de graça e súplicas, seguido de lamento ao olhar para aquele que foi traspassado.','É uma passagem de lamento e arrependimento.','texto_biblico',105),
('zacarias','Zacarias',3,'Na visão de Zacarias 3, quem acusa o sumo sacerdote Josué diante do anjo do Senhor?','facil','O rei da Babilônia','Satanás','Um sacerdote rival','Um profeta falso','B','Zacarias 3:1 descreve Satanás à direita de Josué, o sumo sacerdote, para acusá-lo, mas o Senhor o repreende.','É o acusador por excelência nas Escrituras.','texto_biblico',106),
('zacarias','Zacarias',6,'O que Zacarias vê saindo dentre dois montes de bronze na visão do capítulo 6?','facil','Uma nuvem de fogo apenas','Um exército de anjos armados','Quatro carros puxados por cavalos','Uma frota de navios','C','Zacarias 6:1-8 descreve quatro carros com cavalos de cores diferentes, representando os quatro espíritos dos céus.','São veículos puxados por cavalos de cores distintas.','texto_biblico',107),
('zacarias','Zacarias',8,'Segundo Zacarias 8:23, o que dez homens de todas as línguas farão a um judeu?','medio','Tomarão pela orla de sua veste, dizendo que irão com ele','Pedirão para adorar outros deuses','Ignorarão completamente','Expulsarão da cidade','A','Zacarias 8:23 anuncia que nações desejarão acompanhar o povo judeu, pois reconhecerão que Deus está com eles.','Envolve reconhecimento da presença de Deus com o povo.','texto_biblico',108),
('zacarias','Zacarias',11,'Por quantas moedas de prata o pastor (representando o Senhor) foi avaliado em Zacarias 11:12?','medio','Trinta','Cem','Mil','Dez','A','Zacarias 11:12-13 menciona trinta moedas de prata, valor depois associado à traição de Judas contra Jesus.','É o mesmo valor pago pela traição de Judas no Novo Testamento.','texto_biblico',109),
('zacarias','Zacarias',14,'Em Zacarias 14:4, onde os pés do Senhor se firmarão, fazendo o monte se fender em duas partes?','dificil','Monte Sinai','Monte Carmelo','Monte Nebo','Monte das Oliveiras','D','Zacarias 14:4 descreve os pés do Senhor firmados no monte das Oliveiras, que se fenderá ao meio no dia do Senhor.','É o monte a leste de Jerusalém.','texto_biblico',110),
('malaquias','Malaquias',1,'Qual é a primeira pergunta de contestação registrada no diálogo de Malaquias?','facil','Quem é o rei?','Quando virá Elias?','Onde está Moisés?','Em que nos amaste?','D','Malaquias 1:2 registra a pergunta do povo: em que nos amaste?','Ela vem logo após Deus declarar seu amor por Jacó.','texto_biblico',111),
('malaquias','Malaquias',3,'Quem é prometido como mensageiro antes da chegada do Senhor?','facil','Um general romano','Um mensageiro que prepararia o caminho','Um novo rei assírio','Um sacerdote de Samaria','B','Malaquias 3:1 fala do mensageiro que preparará o caminho diante do Senhor.','A palavra-chave é mensageiro.','texto_biblico',112),
('malaquias','Malaquias',3,'O que Malaquias 3:10 relaciona ao dízimo?','medio','Trazer todos os dízimos à casa do tesouro','Usar o dízimo para guerra','Entregar somente ao rei','Guardar o dízimo em casa','A','Malaquias 3:10 chama a trazer todos os dízimos à casa do tesouro e apresenta a promessa de provisão.','A expressão é casa do tesouro.','texto_biblico',113),
('malaquias','Malaquias',4,'O que o final do livro de Malaquias promete enviar antes do grande e terrível dia do Senhor?','medio','Jeremias','Samuel','Elias, o profeta','Natã','C','Malaquias 4:5 promete enviar Elias, o profeta, antes do grande e terrível dia do Senhor.','É o último nome mencionado no livro.','texto_biblico',114),
('malaquias','Malaquias',2,'Qual problema dos sacerdotes é denunciado em Malaquias 2?','dificil','Desprezavam o nome de Deus e ofereciam sacrifícios inadequados','Não conheciam a Lei de Moisés','Construíam muitos altares','Recusavam-se a trabalhar no templo','A','Malaquias 1–2 denuncia sacerdotes que desprezavam o nome de Deus e aceitavam animais inadequados para sacrifício.','A denúncia envolve a qualidade das ofertas.','texto_biblico',115),
('malaquias','Malaquias',1,'Que tipo de animais o povo oferecia indevidamente em sacrifício, segundo Malaquias 1:8?','facil','Apenas aves selvagens','Cegos, coxos e enfermos','Peixes do rio Jordão','Somente animais gordos e perfeitos','B','Malaquias 1:8 repreende o povo por oferecer animais cegos, coxos e enfermos, desonrando a Deus.','São animais com defeitos físicos.','texto_biblico',116),
('malaquias','Malaquias',2,'O que Malaquias 2:16 diz que o Senhor aborrece?','facil','As orações longas','Os dízimos','Os sacrifícios de louvor','O repúdio (divórcio)','D','Malaquias 2:16 declara que o Senhor Deus de Israel aborrece o repúdio, condenando a infidelidade conjugal.','É relacionado à quebra do casamento.','texto_biblico',117),
('malaquias','Malaquias',3,'O que Malaquias 3:6 afirma sobre o caráter de Deus que garante que Israel não foi consumido?','medio','Eu esqueço facilmente','Eu mudo conforme as nações','Eu abandono meu povo','Eu, o Senhor, não mudo','D','Malaquias 3:6 afirma a imutabilidade de Deus como razão pela qual os filhos de Jacó não foram consumidos.','É uma afirmação sobre a constância do caráter divino.','texto_biblico',118),
('malaquias','Malaquias',3,'De que forma Malaquias 3:8 diz que o povo estava roubando a Deus?','medio','Nos sacrifícios de animais','Nas orações públicas','Nos dízimos e nas ofertas','Na construção do templo','C','Malaquias 3:8 acusa o povo de roubar a Deus retendo dízimos e ofertas.','Está ligado à contribuição financeira ao templo.','texto_biblico',119),
('malaquias','Malaquias',2,'Qual argumento de unidade Malaquias 2:10 usa para repreender a traição entre irmãos?','dificil','Não somos todos sacerdotes?','Não temos todos um mesmo Pai e um mesmo Criador?','Não vivemos todos no Egito?','Não somos todos reis?','B','Malaquias 2:10 apela à paternidade comum de Deus para denunciar a deslealdade entre os israelitas, quebrando a aliança dos pais.','É um apelo à origem e criação comuns.','texto_biblico',120)
